public class Xms98CommandService {

    private final Xrd81Repository userRepository;
    private final Xms98Repository addressRepository;
    private final Xtf80Util encryptionUtil;


    @Transactional
    public void createAddress(String email, Xms98CreateDto createDto) {
        try {
            Xrd81 user = userRepository.findByEmail(email)
                    .orElseThrow(() -> new Xkk16Exception(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            log.info("주소 생성 시작: 사용자={}, 수신자={}", email, createDto.getRecipientName());

            if (createDto.getIsDefault() != null && createDto.getIsDefault()) {

